  <script>
    Chart.defaults.font.family = 'Inter';
    Chart.defaults.color = '#475569';
    Chart.defaults.animation = false;

    const years = {years};

    const annotationsPlugin = {{
      id: 'customAnnotations',
      afterDraw: (chart) => {{
        const ctx = chart.ctx;
        ctx.save();

        // Find 2016 Onshore Wind (Dataset index 3)
        const windMeta = chart.getDatasetMeta(3);
        const windPoint = windMeta.data[6]; // 2016 is index 6

        if (windPoint) {{
            ctx.fillStyle = '#0f172a';
            ctx.font = 'bold 13px Inter';
            ctx.fillText('2016: Wind crosses below', windPoint.x - 70, windPoint.y + 25);
            ctx.font = 'normal 13px Inter';
            ctx.fillStyle = '#475569';
            ctx.fillText('fossil minimum ($56)', windPoint.x - 70, windPoint.y + 40);

            ctx.beginPath();
            ctx.moveTo(windPoint.x - 20, windPoint.y + 15);
            ctx.lineTo(windPoint.x, windPoint.y + 5);
            ctx.strokeStyle = '#94a3b8';
            ctx.lineWidth = 1.5;
            ctx.stroke();
        }}

        // Find 2020 Solar (Dataset index 2)
        const solarMeta = chart.getDatasetMeta(2);
        const solarPoint = solarMeta.data[10]; // 2020 is index 10

        if (solarPoint) {{
            ctx.fillStyle = '#0f172a';
            ctx.font = 'bold 13px Inter';
            ctx.fillText('2020: Solar crosses below', solarPoint.x - 80, solarPoint.y + 30);
            ctx.font = 'normal 13px Inter';
            ctx.fillStyle = '#475569';
            ctx.fillText('fossil range entirely ($42)', solarPoint.x - 80, solarPoint.y + 45);

            ctx.beginPath();
            ctx.moveTo(solarPoint.x - 30, solarPoint.y + 20);
            ctx.lineTo(solarPoint.x, solarPoint.y + 5);
            ctx.strokeStyle = '#94a3b8';
            ctx.lineWidth = 1.5;
            ctx.stroke();
        }}

        // Find 2024 Battery (Dataset index 4)
        const batteryMeta = chart.getDatasetMeta(4);
        const batStart = batteryMeta.data[0]; // 2010
        const batEnd = batteryMeta.data[14]; // 2024

        if (batStart && batEnd) {{
            ctx.fillStyle = '#8b5cf6';
            ctx.font = 'bold 15px Inter';
            ctx.fillText('Battery cost collapses', batStart.x + 30, batStart.y + 15);
            ctx.font = 'bold 14px Inter';
            ctx.fillStyle = '#0f172a';
            ctx.fillText('from $1,100 to $102', batStart.x + 30, batStart.y + 35);
        }}

        ctx.restore();
      }}
    }};

    // 1. LCOE CHART
    new Chart(document.getElementById('lcoeChart'), {{
      type: 'line',
      data: {{
        labels: years,
        datasets: [
          {{
            label: 'Fossil Fuel Max',
            data: {f_max},
            borderColor: 'transparent',
            backgroundColor: 'transparent',
            pointRadius: 0,
            fill: false,
            order: 5
          }},
          {{
            label: 'Fossil Fuel Range',
            data: {f_min},
            borderColor: 'rgba(100, 116, 139, 0.4)',
            borderDash: [5, 5],
            backgroundColor: 'rgba(100, 116, 139, 0.1)',
            fill: '-1',
            pointRadius: 0,
            borderWidth: 1,
            order: 4
          }},
          {{
            label: 'Solar PV',
            data: {solar_lcoe},
            borderColor: '#f59e0b',
            backgroundColor: '#f59e0b',
            borderWidth: 3,
            tension: 0.1,
            pointRadius: 4,
            pointBackgroundColor: '#fff',
            pointBorderWidth: 2,
            order: 2
          }},
          {{
            label: 'Onshore Wind',
            data: {wind_lcoe},
            borderColor: '#0ea5e9',
            backgroundColor: '#0ea5e9',
            borderWidth: 3,
            tension: 0.1,
            pointRadius: 4,
            pointBackgroundColor: '#fff',
            pointBorderWidth: 2,
            order: 3
          }},
          {{
            label: 'Battery Storage',
            data: {battery_lcoe},
            borderColor: '#8b5cf6',
            backgroundColor: '#8b5cf6',
            borderWidth: 3,
            tension: 0.1,
            pointRadius: 4,
            pointBackgroundColor: '#fff',
            pointBorderWidth: 2,
            order: 1
          }}
        ]
      }},
      plugins: [annotationsPlugin],
      options: {{
        responsive: true,
        maintainAspectRatio: false,
        plugins: {{
          legend: {{ display: false }},
          tooltip: {{ enabled: true }}
        }},
        scales: {{
          x: {{
            grid: {{ display: false }},
            ticks: {{ font: {{ size: 13, weight: '500' }} }}
          }},
          y: {{
            type: 'logarithmic',
            grid: {{ color: 'rgba(0,0,0,0.06)' }},
            min: 20,
            max: 1500,
            ticks: {{
              font: {{ size: 13, weight: '500' }},
              callback: function(value) {{
                const allowed = [20, 30, 50, 100, 200, 500, 1000];
                if (allowed.includes(value)) return '$' + value;
                return '';
              }}
            }}
          }}
        }},
        layout: {{ padding: {{ top: 20, right: 20, bottom: 10, left: 10 }} }}
      }}
    }});

    // 2. CAPACITY CHART
    new Chart(document.getElementById('capacityChart'), {{
      type: 'line',
      data: {{
        labels: years,
        datasets: [
          {{
            label: 'Solar PV',
            data: {solar_cap},
            borderColor: '#f59e0b',
            backgroundColor: 'rgba(245, 158, 11, 0.15)',
            borderWidth: 3,
            fill: true,
            tension: 0.3,
            pointRadius: 0,
            pointHoverRadius: 4
          }},
          {{
            label: 'Onshore Wind',
            data: {wind_cap},
            borderColor: '#0ea5e9',
            backgroundColor: 'rgba(14, 165, 233, 0.15)',
            borderWidth: 3,
            fill: true,
            tension: 0.3,
            pointRadius: 0,
            pointHoverRadius: 4
          }}
        ]
      }},
      options: {{
        responsive: true,
        maintainAspectRatio: false,
        plugins: {{
          legend: {{
            position: 'top',
            align: 'end',
            labels: {{ usePointStyle: true, boxWidth: 8, font: {{ size: 13, weight: '500' }} }}
          }}
        }},
        scales: {{
          x: {{ grid: {{ display: false }}, ticks: {{ maxTicksLimit: 8 }} }},
          y: {{
            grid: {{ color: 'rgba(0,0,0,0.06)' }},
            ticks: {{ callback: function(value) {{ return value + ' GW'; }} }}
          }}
        }}
      }}
    }});

    // 3. SUBSIDY CHART
    new Chart(document.getElementById('subsidyChart'), {{
      type: 'bar',
      data: {{
        labels: years,
        datasets: [
          {{
            label: 'Consumption Subsidies',
            data: {subs_cons},
            backgroundColor: '#94a3b8'
          }},
          {{
            label: 'Production Subsidies',
            data: {subs_prod},
            backgroundColor: '#475569'
          }}
        ]
      }},
      options: {{
        responsive: true,
        maintainAspectRatio: false,
        plugins: {{
          legend: {{
            position: 'top',
            align: 'end',
            labels: {{ usePointStyle: true, boxWidth: 8, font: {{ size: 13, weight: '500' }} }}
          }}
        }},
        scales: {{
          x: {{ stacked: true, grid: {{ display: false }}, ticks: {{ maxTicksLimit: 8 }} }},
          y: {{
            stacked: true,
            grid: {{ color: 'rgba(0,0,0,0.06)' }},
            ticks: {{ callback: function(value) {{ return '$' + value + 'B'; }} }}
          }}
        }}
      }}
    }});
  </script>
</body>
</html>
